INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('f2d9fe75-0982-4f1e-b9bd-b8977339eb09', '21feff02-016d-46e2-bb9d-c27495133b1b', '110. óra: Testek térfogata', 'Téglatest és kocka térfogatának (V) kiszámítása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "c494336a-4f5e-4891-b24c-e938cb30e953", "text": "Mi a kocka térfogatának képlete (''a'' éllel)?", "type": "multiple-choice", "options": [{"id": "222069cd-120d-4b89-a2d1-ade0d1c79d52", "text": "V = a * a * a (a³)", "isCorrect": true}, {"id": "1df553c9-78e0-4a72-91bb-099ca52c7740", "text": "V = 6 * a²", "isCorrect": false}, {"id": "1e8969fa-f33a-4217-9ca7-ce9f220e1465", "text": "V = 12 * a", "isCorrect": false}, {"id": "0c9a2051-a205-4363-b14c-78ade6bac0b6", "text": "V = a + a + a", "isCorrect": false}], "timeLimit": 15}, {"id": "cf9ef540-2610-4764-8b65-7f9307d9c21b", "text": "Mi a téglatest térfogatának képlete (a, b, c élekkel)?", "type": "multiple-choice", "options": [{"id": "cf9bdd01-8617-49d5-8b80-e8dede3fe358", "text": "V = a * b * c", "isCorrect": true}, {"id": "50501fa1-6f0e-458d-a6be-4786b336c909", "text": "V = 2 * (a+b+c)", "isCorrect": false}, {"id": "2a5743f5-07b6-4102-8c97-3e09251c5144", "text": "V = a * b", "isCorrect": false}, {"id": "1d873c3d-5d01-49ac-a259-92d87c9baebd", "text": "V = a + b + c", "isCorrect": false}], "timeLimit": 15}, {"id": "3095bd78-444c-4bfb-b193-e4bea774bc8d", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "967f30b9-4f44-41bd-b66f-463832b04d98", "text": "Mennyi a 2 cm, 4 cm, 5 cm élű téglatest térfogata? (2 * 4 * 5)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "40"}, {"id": "8d13c209-1f16-4da0-a2db-8c0cd7e58e13", "text": "A térfogatot mindig köbmértékegységben (cm³, m³, dm³) vagy űrmértékben (liter, dl) adjuk meg.", "type": "true-false", "options": [{"id": "f7914fce-e54a-43d0-976b-52d2a28c4cc2", "text": "Igaz", "isCorrect": true}, {"id": "3750793b-885a-44d6-832b-f5a6b15ef63c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "7f5c2cdf-8511-49d9-beeb-e34db66c5e24", "text": "Mennyi a 4 cm élű kocka térfogata? (4 * 4 * 4)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "28870db8-1134-4bd4-8bf8-76005b8ce547", "text": "Mennyi a 10 cm élű kocka térfogata cm³-ben? (1000 cm³ = 1 liter)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('0832957a-9fa9-40b3-86cf-0bcbc7a6a2c4', '21feff02-016d-46e2-bb9d-c27495133b1b', '111. óra: Projektóra', 'Épülettervezés I. - Vetületi képek megrajzolása, makett alaprajzának elkészítése.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "17b9d08c-f6a5-419c-8bf1-5efb78c14579", "text": "Mit mutat meg egy épület felülnézete (alaprajza)?", "type": "multiple-choice", "options": [{"id": "22d89041-8403-449d-977e-9c150ec54705", "text": "Az épület felülről látható elrendezését és méreteit", "isCorrect": true}, {"id": "e458ec87-7cca-4d49-b31f-1f787b0e1859", "text": "A tető színét", "isCorrect": false}, {"id": "ca1e8ff3-20f7-44c3-a2e6-41f48f2aad27", "text": "Az épület magasságát", "isCorrect": false}, {"id": "5881e283-38b2-4241-8b82-0a78b58c5240", "text": "Az ablakok mintáját", "isCorrect": false}], "timeLimit": 15}, {"id": "a24a16fa-a081-422e-b60d-0b93438e7e53", "text": "Egy épület makettjének elkészítése segít a térbeli arányok megértésében.", "type": "true-false", "options": [{"id": "98cb6f70-c496-44fb-9bd2-e45fadd6bcde", "text": "Igaz", "isCorrect": true}, {"id": "ed696787-e006-4bf4-8b21-0f610612060f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "55c34ab3-c527-4e86-a83f-0756fae9f623", "text": "Hány m² az 5 m x 6 m-es alaprajzú házalap területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "e086b137-1705-46a1-96c6-5c085663d796", "text": "A méretarányos rajz készítése elengedhetetlen az építészetben.", "type": "true-false", "options": [{"id": "e12a0c20-0ec0-4137-b62b-f635ece7d23b", "text": "Igaz", "isCorrect": true}, {"id": "7c114a97-658c-4c97-ad65-cb5389eeda4f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "09cb9c51-5afe-4df5-b207-3a7619eb8afe", "text": "Ha az 1:100 méretarányú rajzon a fal 5 cm, hány méter a valóságban? (5 * 100 cm)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "bdb0217b-2b41-4f37-9845-4a8b63d61008", "text": "A csoportszervezés és munkamegosztás felgyorsítja a projekt elvégzését.", "type": "true-false", "options": [{"id": "c83bbdde-ecc4-43ec-aea2-3d04702030d2", "text": "Igaz", "isCorrect": true}, {"id": "84633628-1865-4178-ba2a-cb46b6a17c2c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "8ef6f3d7-5520-4820-ba41-46a5c961cebb", "text": "Hány oldallapja van a téglatest alakú épületnek?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('b47f4095-fa4b-4b46-a40a-ef8d366079cf', '21feff02-016d-46e2-bb9d-c27495133b1b', '112. óra: Projektóra II.', 'Épülettervezés II. - Makett megépítése kartonból, legóból, egységkockákból.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e7374859-4821-43ed-9314-02eff9bf44ff", "text": "Hány darab 1 cm³-es kiskockára van szükség egy 3 cm x 4 cm x 5 cm-es épületmakett megépítéséhez?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "60"}, {"id": "e15b7df2-63e9-4dd4-8185-b3bbc046cbc6", "text": "Az épületmakett térfogata megegyezik a felhasznált egységkockák térfogatának összegevel.", "type": "true-false", "options": [{"id": "14a91c11-e146-48be-a50e-a3e14af91014", "text": "Igaz", "isCorrect": true}, {"id": "4381006d-ba13-452b-b2e4-ce3646c12978", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f1d3522-384f-42cd-a469-62c68c2df967", "text": "Melyik testből építhető fel a legkönnyebben téglatest alakú ház?", "type": "multiple-choice", "options": [{"id": "d6749630-fdb5-4c17-8f66-aed3f690b0ee", "text": "Egységkockákból / kartondobozból", "isCorrect": true}, {"id": "d1959aa4-344b-4711-b638-e7dbd447247e", "text": "Gömbökből", "isCorrect": false}, {"id": "cae6f91b-a6e7-482a-b538-a71572bec032", "text": "Kúpokból", "isCorrect": false}, {"id": "a3c28bd7-3996-4513-9c1c-e8a94109d2f8", "text": "Hengerekből", "isCorrect": false}], "timeLimit": 15}, {"id": "086473fe-584b-4571-b4c1-2aa5d0a5c9fd", "text": "A makett készítése során a stabil szerkezet kialakítása a cél.", "type": "true-false", "options": [{"id": "b82e0c0d-7d71-4fbc-8dc9-b534d990a5b2", "text": "Igaz", "isCorrect": true}, {"id": "2cfa2e43-1150-4639-ba16-733b02e21f1d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "febaf40d-3d1c-4b6a-bc65-0778be60bab1", "text": "Mennyi a 2 cm élű kockákból álló 2x2x2-es házikó térfogata? (8 * 8 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "8a8dc13c-e2ed-403c-bf1e-c5871e9af471", "text": "A projektmunka kreatív megoldásokat ösztönöz.", "type": "true-false", "options": [{"id": "0482055f-b541-4dfd-83c6-0a78d620c4fb", "text": "Igaz", "isCorrect": true}, {"id": "cfe6b381-a717-477e-a24a-669d242ffaf9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "84f0a0ef-6d53-4481-864d-54478c157156", "text": "Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('8f49924c-6f4b-4b8e-9ee7-fb27ad192de9', '21feff02-016d-46e2-bb9d-c27495133b1b', '113. óra: Projektóra III.', 'Az elkészített projektek és makettek bemutatása, csoportértékelés.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "642b4f0c-b8d0-4038-a792-cc35a27ff6e8", "text": "Mi a projekt bemutatásának legfőbb értéke?", "type": "multiple-choice", "options": [{"id": "7fa5cd2e-09c4-4365-9cbf-338295a5e7f4", "text": "Az elvégzett munka, a mérések, számítások és az elkészült makett ismertetése", "isCorrect": true}, {"id": "b91fe531-c0b4-4e44-8e06-3f1e4f9b54b9", "text": "Gyors befejezés elnémulva", "isCorrect": false}, {"id": "076c01ce-9829-4d79-b910-018efed5414a", "text": "Más csoportok munkájának elrejtése", "isCorrect": false}, {"id": "058728b5-5c70-462c-9e9d-ffc192ad9019", "text": "Csak a színek felsorolása", "isCorrect": false}], "timeLimit": 15}, {"id": "919876d8-8635-4b58-b045-52a60a32becb", "text": "A prezentációs készség és a szaknyelv használata fontos részét képezi az értékelésnek.", "type": "true-false", "options": [{"id": "4de752a5-46d4-492c-9576-b67603e63116", "text": "Igaz", "isCorrect": true}, {"id": "0a635eeb-1411-4147-b592-624444a027b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2bdcaa3e-f431-4086-837d-9c990a8bd167", "text": "Az önértékelés és a társak építő kritikája segít a fejlődésben.", "type": "true-false", "options": [{"id": "b451b886-09d4-4d10-b97b-06b84256b25d", "text": "Igaz", "isCorrect": true}, {"id": "05cb3de4-d6a9-4d3b-8cc7-051bfedd6ae3", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fff9d629-ef6a-4000-be7e-3cf33409db18", "text": "Mennyi a 10 cm x 10 cm x 10 cm-es kockamakett térfogata literekben? (1000 cm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1"}, {"id": "c66686dd-88cf-4cf4-adff-593e4ff42095", "text": "A projektmunka során a csoport minden tagjának részfeladatot kell vállalnia.", "type": "true-false", "options": [{"id": "2aeaaff0-488e-4349-a8d3-d8a4521ae287", "text": "Igaz", "isCorrect": true}, {"id": "13e49af2-11b1-4d31-8b2c-844af4bc9c8e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b7a20559-7ab6-4a73-a772-dca4685262f5", "text": "A térszemlélet fejlesztése elengedhetetlen a 3D-s tervezéshez.", "type": "true-false", "options": [{"id": "1a92ed38-a297-4e01-8be7-598f3d8f0494", "text": "Igaz", "isCorrect": true}, {"id": "25b31a29-869b-4cca-b0f8-42b7a1361b67", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ec82e925-3cc5-4d86-881c-6a6658194cd0", "text": "Mennyi 1 m³ dm³-ben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1000"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ff064ae7-0720-43c2-9f11-04259d0ad77d', '21feff02-016d-46e2-bb9d-c27495133b1b', '114. óra: Összefoglalás', 'A Kerület, terület, felszín és térfogat fejezet összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "e38f6937-3323-48b3-a22e-7569a4785fc6", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "17e03d3a-7573-47b9-a64d-6b4ad2ca0695", "text": "Mennyi a 5 cm és 6 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "22"}, {"id": "d5627c2d-436d-496f-9e9b-14ef91aadd02", "text": "Mennyi a 3 cm élű kocka felszíne? (6 * 9)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "3f4db0cd-d83f-4c0f-8836-c137b8088b27", "text": "Mennyi a 3 cm élű kocka térfogata? (3 * 3 * 3)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "27"}, {"id": "061d79e4-c7cc-4332-b529-c0c78faf0ecd", "text": "1 liter víz térfogata 1 dm³.", "type": "true-false", "options": [{"id": "f86ef17c-84a9-40e9-8567-cf04d7239317", "text": "Igaz", "isCorrect": true}, {"id": "16b28d52-d1fc-40fd-b696-724cf3cb2cfa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f1bffd4-cbba-46cf-bb40-870bfe43076e", "text": "Hány cm² 1 m²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "10000"}, {"id": "0a89c247-444c-42d0-aa29-e91f66061a07", "text": "A kerület 1D (hosszúság), a terület 2D, a térfogat 3D mennyiség.", "type": "true-false", "options": [{"id": "336e3d04-4b0e-432a-ad90-91272a03eec9", "text": "Igaz", "isCorrect": true}, {"id": "efd9fba6-6573-4f3d-9922-67139633d8c4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('78410cc9-433f-4f1e-9cd6-e766eb843001', '21feff02-016d-46e2-bb9d-c27495133b1b', '115. óra: Gyakorlóóra', 'Gyakorló feladatsor önálló megoldása a mérések témakörben.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "07028272-8449-44e4-9474-0d3ae819409f", "text": "Mennyi a 8 cm és 4 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "32"}, {"id": "cf667fca-f9f5-4c07-abfd-21bf2b41d667", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "c7c878ca-41b4-443b-8e86-6308a86bf162", "text": "Mennyi a 2 cm, 3 cm, 5 cm élű téglatest felszíne? (2*(6+10+15) = 2*31)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "62"}, {"id": "73480443-493e-4457-ab48-ba4387c88dc6", "text": "A 1000 dm³ megegyezik 1 m³-rel.", "type": "true-false", "options": [{"id": "a7661f63-5c99-41fb-a757-5e9f1afe39bd", "text": "Igaz", "isCorrect": true}, {"id": "bcbfbde6-ab2d-4d6b-8add-74e52ef6e263", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "b4d3347f-73d4-4c35-9f53-3c7602c6dd72", "text": "Hány liter üdítő van egy 2500 cm³-es tartályban? (2,5 dm³)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2.5"}, {"id": "51eb1922-2d79-49c1-a32d-1ad38f71c750", "text": "A méréseknél az azonos mértékegységre való áttérés a sikeres számolás alapja.", "type": "true-false", "options": [{"id": "9348207c-1bdd-4e62-b1ea-b6047bd8a449", "text": "Igaz", "isCorrect": true}, {"id": "6070d553-68d1-4c08-a967-16f1f8a67a82", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "760fe80e-45b1-4965-a47a-9da0ac1910b9", "text": "Mennyi a 6 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d57eb83c-1a34-4d16-b822-916c45c7f995', '21feff02-016d-46e2-bb9d-c27495133b1b', '116. óra: Feladatmegoldás', 'Hétköznapi mérésekkel, kerülettel, területtel és térfogattal kapcsolatos feladatok.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "54694eea-4404-4eee-a2f1-17d3a8f7757b", "text": "Egy 10 m x 8 m-es medence 2 m mély. Hány m³ víz fér a medencébe tele állapotban? (10 * 8 * 2)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160"}, {"id": "fc8402f3-6003-4972-86df-fd46794b3c54", "text": "Hány liter víz fér a 160 m³-es medencébe? (160 * 1000)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "160000"}, {"id": "80ce98cc-e5ea-4460-b8ea-20c91ce45d19", "text": "Hány m² csempe kell a medence padlójának leburkolásához? (10 * 8)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "80"}, {"id": "6afd68c6-afda-43dc-94aa-eb81f2c602b4", "text": "A medence térfogata megadja a maximális vízkapacitást.", "type": "true-false", "options": [{"id": "1428404b-92cc-4b5c-baa1-b635bc785df9", "text": "Igaz", "isCorrect": true}, {"id": "0a462548-7a88-4769-a4a5-1d1f5e5991aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c5eb2cee-b3a6-43f3-99e6-ce7a4656e44b", "text": "Mennyi a 4 m élű kocka alakú szoba térfogata? (m³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "921552eb-050d-4f0e-b374-5601a4a3b03b", "text": "Mennyi a 4 m élű kocka alakú szoba felszíne? (m²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "96"}, {"id": "41a62c45-c8e2-4b02-b80b-0a23da8ee505", "text": "A gyakorlati feladatok megoldása felkészít a mindennapi életmérésekre.", "type": "true-false", "options": [{"id": "95cc1fe7-8998-4d4c-b091-6f4c3edb337e", "text": "Igaz", "isCorrect": true}, {"id": "66150c47-cd4c-4a84-addb-00fa18b616c4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('cb57c1c8-4edf-4bc3-898f-24cfaaa82605', '21feff02-016d-46e2-bb9d-c27495133b1b', '117. óra: Témazáró dolgozat', 'Témazáró számonkérés a Kerület, terület, felszín és térfogat fejezetből (10 kérdés).', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "9a80f779-cceb-49a9-9f99-baa14a478df6", "text": "1. Mennyi a 6 cm és 9 cm oldalú téglalap területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "54"}, {"id": "3119fdfc-0dd1-4593-af47-4b75a7ff5c75", "text": "2. Mennyi a 6 cm és 9 cm oldalú téglalap kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "0d355edb-4097-4bf1-9798-2c00a3515da1", "text": "3. Mennyi a 5 cm élű kocka felszíne? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "150"}, {"id": "fbb87534-0cfd-41a8-a371-85335baae107", "text": "4. Mennyi a 5 cm élű kocka térfogata? (cm³-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "125"}, {"id": "2c63ee89-5808-425d-a211-01776be825d4", "text": "5. Mennyi a 3 cm, 4 cm, 6 cm élű téglatest térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}, {"id": "0fb5ba71-a86f-4002-808a-3dfd942802cf", "text": "6. Hány cm² 4 dm²?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "400"}, {"id": "67cfa0d5-9ccc-4631-8b89-e2b8dc2e87cc", "text": "7. Hány dm³ 3 m³?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3000"}, {"id": "fa54556f-a64e-4e1d-ace0-bf8072cf1f6e", "text": "8. Hány liter víz fér el 5 dm³-es edényben?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "5"}, {"id": "a83acee0-7917-4fe6-87b5-fa5a972955a5", "text": "9. A derékszögű háromszög területe a befogók szorzatának fele.", "type": "true-false", "options": [{"id": "33b0480c-09b3-496a-9eb8-9ee46d8b47c0", "text": "Igaz", "isCorrect": true}, {"id": "f6aaafff-349c-41cd-b856-0d7ec4108c66", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "082356b4-3c64-4394-ba92-7fe1d752d8bb", "text": "10. Hány éle van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('64d8a29f-c75e-4fac-9839-837835b95066', '21feff02-016d-46e2-bb9d-c27495133b1b', '118. óra: Témazáró dolgozat értékelése', 'A témazáró dolgozat megbeszélése és a mérések összefoglalása.', 'Matematika', '6. osztály', 'Kerület, terület, felszín, térfogat', '[{"id": "33d8c4a4-ebc2-4b95-aa66-25eedd1f733b", "text": "Mi volt a leggyakoribb hiba a felszín- és térfogatszámítás során?", "type": "multiple-choice", "options": [{"id": "83c0a5d3-c58f-479c-af78-a35ddb6d6d61", "text": "A képletek és mértékegységek (cm² vs cm³) összetévesztése", "isCorrect": true}, {"id": "38091806-a969-4097-af82-a1c2c0643e5a", "text": "A ceruza radírozása", "isCorrect": false}, {"id": "690493e1-659d-47c4-a202-a5ea45da49db", "text": "A számláló írása", "isCorrect": false}, {"id": "7804a360-7f91-4fbe-9856-abcb34084253", "text": "Az összeadás hiánya", "isCorrect": false}], "timeLimit": 15}, {"id": "7589a106-39e3-4882-a76e-c2f3bb86c74b", "text": "A térfogat a test által elfoglalt térrész nagyságát jelenti.", "type": "true-false", "options": [{"id": "c7a62ebf-58b1-4bb5-b493-beb4d4051289", "text": "Igaz", "isCorrect": true}, {"id": "63a9e806-9476-4997-b319-ddc472862cc6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3478135f-b921-4388-ae9b-5d852dc5bb55", "text": "Mennyi a 2 cm élű kocka térfogata?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}, {"id": "9cc7ce80-0bdb-43ae-a1d1-d108c6d43911", "text": "Mennyi a 2 cm élű kocka felszíne?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "24"}, {"id": "39dcfaab-90cd-45c4-a78d-469b86781b87", "text": "A mértékegységek helyes megadása a válasz kötelező eleme.", "type": "true-false", "options": [{"id": "45bb64e1-26a3-444f-8cc6-a3da7348b37b", "text": "Igaz", "isCorrect": true}, {"id": "a314b458-adb9-4ada-ba77-a486358178f2", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "21956af3-d171-4274-8a79-8364b73356c1", "text": "Mennyi a 4 cm és 3 cm befogójú derékszögű háromszög területe?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "5c5aac24-fba9-47a5-928d-fd9eeb24abd6", "text": "A hibajavítás segít a pontosabb tudás megszilárdításában.", "type": "true-false", "options": [{"id": "4d984fc3-d0f3-4c27-9afe-adf66a189832", "text": "Igaz", "isCorrect": true}, {"id": "c620d781-1f41-4e49-a144-1bb8e05bd32d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('41b2c889-f6ac-464a-a8a7-a6e07762f4b8', '21feff02-016d-46e2-bb9d-c27495133b1b', '119. óra: Játék', 'Adatgyűjtési kifejezések, játékszabályok értelmezése, megfigyelés.', 'Matematika', '6. osztály', 'Statisztika', '[{"id": "b3293e8e-d2af-4c53-a8aa-e597ccfa99ba", "text": "Mi a statisztika fő célja?", "type": "multiple-choice", "options": [{"id": "4b6150bb-4bcc-48b2-81a4-42404bb4b438", "text": "Adatok gyűjtése, rendszerezése, ábrázolása és elemzése a döntéshozatalhoz", "isCorrect": true}, {"id": "00df13d6-dbb6-4ede-adb0-0053acdadeb2", "text": "Színes rajzok készítése", "isCorrect": false}, {"id": "669428d7-58e7-40ef-85a6-e9ce8e539ab5", "text": "Számok törlése", "isCorrect": false}, {"id": "d35cb14e-1b9f-4f86-a79d-6902b394b987", "text": "Csak a legnagyobb szám megtalálása", "isCorrect": false}], "timeLimit": 15}, {"id": "971c62a6-d2cf-4ec9-9b85-a80fd7099ea9", "text": "Az adatok gyűjtése történhet megfigyeléssel, méréssel vagy kérdőívvel.", "type": "true-false", "options": [{"id": "37c9e45a-cfb4-42bb-a623-3cbbbc58959f", "text": "Igaz", "isCorrect": true}, {"id": "2c727def-a7ec-483a-a9f3-5870e5b50c3f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9d699e55-c0d5-4a6e-88cf-79cb24580f17", "text": "Melyik nem statisztikai adatgyűjtési módszer?", "type": "multiple-choice", "options": [{"id": "e8af9750-dbe9-4ad0-8009-efb25a676161", "text": "Alvás", "isCorrect": true}, {"id": "1b9246ea-fedf-4f9e-8b67-8cfd9dc9a08a", "text": "Kérdőíves felmérés", "isCorrect": false}, {"id": "d0cb8a78-8752-46cc-8e1d-bf5fcc716fda", "text": "Hőmérséklet-mérés", "isCorrect": false}, {"id": "cc022df1-e072-4147-9064-c22434aa57b0", "text": "Szavazás", "isCorrect": false}], "timeLimit": 15}, {"id": "8d75748f-63a1-4726-8453-1751342e276f", "text": "A gyűjtött adatokat áttekinthető módon táblázatba foglalhatjuk.", "type": "true-false", "options": [{"id": "78a975da-0b9b-4cfd-b0f8-37135246d44d", "text": "Igaz", "isCorrect": true}, {"id": "45bf7a54-16fd-4a31-84e1-4c82f01316c9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2c70cfcb-9eef-450e-b0c4-a95cdfe43489", "text": "Hány válaszlehetőség van egy ''igen/nem'' típusú kérdésnél?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "b3c5c296-d4e4-4b9d-830c-2a0152a57b1a", "text": "A statisztikai mintavétel során a cél a pontos és torzításmentes adatszerzés.", "type": "true-false", "options": [{"id": "29f0d7ab-dad8-433c-8fff-e6abb3d1a7d3", "text": "Igaz", "isCorrect": true}, {"id": "5a3e197a-94bc-4a1b-bf5a-0693211e658c", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "9704e39b-1d9d-4766-bfd8-615b74930973", "text": "Az adatok rendszerezése megkönnyíti a döntéshozatalt.", "type": "true-false", "options": [{"id": "b5793a94-7027-4f7b-b84c-24309ec25406", "text": "Igaz", "isCorrect": true}, {"id": "7de1148c-32ff-445d-9970-44ffca68a890", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW());